from __future__ import annotations
from .canonical import stable_id,with_digest
from .policies import CLAIM_CEILING,SECTION_IDS
def build(req:dict,binding:dict,contracts:dict,readiness:dict,decision:dict,execution:dict,created_at:str)->tuple[dict,dict]:
    report=with_digest({'schema_version':'1.0.0','report_id':stable_id('PILOTREPORT',req['pilot_request_id'],decision['pilot_readiness_decision_digest'],length=32),'created_at':created_at,'context_id':req['context_id'],'context_version':req['context_version'],'claim_ceiling':CLAIM_CEILING,'section_order':SECTION_IDS,'evidence_classification':req['evidence_classification'],'real_context_evidence_present':req['real_context_evidence_present'],'source_assessment_run_id':binding['assessment_run_id'],'pilot_contract_id':contracts['contract']['pilot_contract_id'],'readiness_state':decision['state'],'readiness_status_counts':readiness['status_counts'],'pilot_ready_non_capital':decision['pilot_ready_non_capital'],'pilot_execution_materialized':execution['pilot_execution_materialized'],'limitations':['Reference fixture is not real market evidence.','No prospective pilot outcomes exist.','No validation, alpha, runtime, live-order or capital claim is allowed.','Production security remains not ready.'],'next_allowed_actions':['Provide approved real Context evidence and independent owner approvals.','Externally verify availability semantics.','Rebuild the immutable pilot package before any prospective observation begins.']},'pilot_design_report_digest')
    executive=with_digest({'schema_version':'1.0.0','report_id':report['report_id'],'answer_first':'The pilot contract is authored, but real Context evidence and approvals are still required before a non-capital pilot may start.' if not decision['pilot_ready_non_capital'] else 'The real Context pilot contract is ready for separate non-capital execution authorization; no pilot has run.','state':decision['state'],'satisfied_gates':readiness['status_counts']['SATISFIED'],'unknown_gates':readiness['status_counts']['UNKNOWN'],'unsatisfied_gates':readiness['status_counts']['UNSATISFIED'],'pilot_execution_allowed':False,'validation_claim_allowed':False,'alpha_claim_allowed':False,'live_order_submission_allowed':False,'capital_activation_allowed':False},'executive_brief_digest')
    return report,executive
